css:
[data-bz-section="utility-bar"] .bz-section { background: var(--ink); color: #fff; font-size: var(--text-small) }
[data-bz-section="utility-bar"] [data-bz-node="ub-left"],
[data-bz-section="utility-bar"] [data-bz-node="ub-right"] { display: flex; align-items: center; gap: var(--space-5); flex-wrap: wrap }
[data-bz-section="utility-bar"] [data-bz-node="ub-right"] { justify-content: flex-end }
[data-bz-section="utility-bar"] .bz-btns { margin-block: 0 }
[data-bz-section="utility-bar"] .bz-btn--secondary { background: none; border: 0; padding: 0; min-height: 0; color: #fff; font-weight: 700 }
[data-bz-section="utility-bar"] [data-bz-node="ub-address"] p { margin: 0; color: rgba(255,255,255,.72) }
[data-bz-section="utility-bar"] .bz-menu--horizontal { gap: 28px }
[data-bz-section="utility-bar"] .bz-navitem > a { color: rgba(255,255,255,.85); font-size: var(--text-small); font-weight: 500; padding: 0 }
[data-bz-section="utility-bar"] .bz-navitem > a:hover { color: #fff }
/* Below 900px the bar becomes one line: the phone and the social row. The
   address and the utility links both have a home in the footer, and four
   stacked lines of chrome would push the hero off the first screen. */
@media (max-width: 900px) {
  [data-bz-section="utility-bar"] [data-bz-node="ub-row"] { display: flex; flex-wrap: nowrap; align-items: center; justify-content: space-between; column-gap: var(--space-4) }
  [data-bz-section="utility-bar"] [data-bz-node="ub-row"] > .bz-col { width: auto; flex: 0 0 auto }
  [data-bz-section="utility-bar"] [data-bz-node="ub-address"],
  [data-bz-section="utility-bar"] [data-bz-node="ub-menu"] { display: none }
}
